<script>
(function(){
  var goal=document.getElementById('sgGoal'),have=document.getElementById('sgHave'),
      monthly=document.getElementById('sgMonthly'),apy=document.getElementById('sgApy'),
      timeEl=document.getElementById('sgTime'),detEl=document.getElementById('sgDetail');
  function money(n){return '$'+Math.round(n).toLocaleString('en-US');}
  function dur(m){var y=Math.floor(m/12),mo=m%12;var s=[];if(y)s.push(y+(y===1?' year':' years'));if(mo)s.push(mo+(mo===1?' month':' months'));return s.join(' ')||'0 months';}
  function calc(){
    var g=parseFloat(goal.value)||0, h=parseFloat(have.value)||0,
